export const machineMechanics = [
  {id:'lever',label:'Brazo de palanca',title:'Brazo rígido con apoyo o discos',example:'Ejemplo: extensión de rodilla con brazo acolchado o máquina de placas.',formula:'Torque de la máquina ≈ fuerza transmitida × distancia perpendicular al eje de la máquina.',diagram:`<svg viewBox="0 0 320 150" role="img" aria-label="Palanca de máquina con eje, resistencia y apoyo"><line x1="35" y1="82" x2="277" y2="82" class="machine-bar"/><circle cx="90" cy="82" r="9" class="machine-pivot"/><path d="M75 121 L90 91 L105 121 Z" class="machine-fulcrum"/><circle cx="245" cy="82" r="9" class="machine-load"/><line x1="245" y1="37" x2="245" y2="68" class="machine-force"/><path d="M239 63 L245 74 L251 63" class="machine-arrow"/><text x="76" y="143">Eje</text><text x="213" y="143">Apoyo / carga</text><text x="31" y="61">brazo de resistencia</text></svg>`,mechanism:'La carga se transmite a un brazo que gira alrededor de un eje. La posición del disco, el punto de apoyo y el brazo de conexión determinan el torque de la máquina. En el cuerpo, el torque externo de la rodilla depende además de la fuerza del cojín y de su distancia perpendicular a la rodilla.',watch:'Alinea el eje mecánico con la articulación indicada y ajusta el rodillo para que apoye sobre la parte distal de la pierna sin presionar el tobillo. La geometría cambia entre diseños; no infieras la carga articular solo por los kilos seleccionados.',sources:['simplemachines','machinelever','torque']},
  {id:'cam',label:'Leva variable',title:'Leva que cambia el brazo efectivo',example:'Ejemplo: extensión de rodilla o curl de codo con leva.',formula:'Torque de la máquina = tensión del cable × radio efectivo de la leva.',diagram:`<svg viewBox="0 0 320 150" role="img" aria-label="Leva de radio variable que tira de un cable"><path d="M151 26 C191 27 216 50 211 82 C207 112 178 126 150 120 C120 114 109 92 116 68 C122 45 131 31 151 26Z" class="machine-cam"/><circle cx="160" cy="77" r="7" class="machine-pivot"/><line x1="160" y1="77" x2="211" y2="82" class="machine-radius"/><line x1="211" y1="82" x2="280" y2="42" class="machine-cable"/><text x="45" y="35">perfil de leva</text><text x="172" y="68">radio efectivo</text><text x="246" y="32">cable</text></svg>`,mechanism:'Al girar la leva, cambia la distancia perpendicular entre su eje y la línea de tracción del cable. Esto modifica el torque de resistencia a lo largo del recorrido. Un perfil puede diseñarse para variar la resistencia; no garantiza que coincida con la curva de fuerza de cada persona.',watch:'Compara inicio, mitad y final del recorrido. El cambio de sensación puede venir del radio de la leva, de la longitud muscular, del brazo interno del músculo y de la postura. Un estudio de extensión de rodilla encontró perfiles de torque distintos al comparar leva y polea semicircular.',sources:['camstudy','machinelever','torque']},
  {id:'pulley',label:'Poleas',title:'Polea fija, móvil o compuesta',example:'Ejemplo: polea alta, baja o sistema de cable con varias roldanas.',formula:'Ventaja ideal ≈ número de tramos de cuerda que sostienen la carga móvil.',diagram:`<svg viewBox="0 0 320 150" role="img" aria-label="Sistema de poleas con cuerda, carga y tramos de soporte"><line x1="58" y1="22" x2="258" y2="22" class="machine-frame"/><circle cx="116" cy="48" r="19" class="machine-sheave"/><circle cx="176" cy="91" r="19" class="machine-sheave moving"/><path d="M97 48 V91 A19 19 0 0 0 135 91 V48 A19 19 0 0 1 173 48 V91 A19 19 0 0 0 211 91 V46" class="machine-cable"/><rect x="159" y="113" width="34" height="24" rx="3" class="machine-load"/><line x1="271" y1="29" x2="271" y2="81" class="machine-force"/><path d="M265 75 L271 86 L277 75" class="machine-arrow"/><text x="230" y="111">tirón</text><text x="48" y="143">la carga puede requerir más recorrido de cuerda</text></svg>`,mechanism:'Una polea fija cambia principalmente la dirección del tirón; idealmente su ventaja mecánica es 1:1. En un sistema con polea móvil, varios tramos sostienen la carga y pueden reducir la fuerza necesaria a cambio de tirar más cuerda. La fricción y el diseño real modifican la ventaja.',watch:'No asumas que el número de la placa equivale a la fuerza exacta en la mano: revisa cuántos tramos sostienen la carga y la relación indicada por el fabricante. La razón de poleas modifica la fuerza del cable, no el brazo interno del músculo.',sources:['simplemachines']},
  {id:'plate',label:'Brazo con discos',title:'Máquina de carga libre o placas',example:'Ejemplo: prensa, remo o press de pecho con discos montados en brazos.',formula:'Torque de los discos ≈ peso × distancia perpendicular entre su línea de gravedad y el eje.',diagram:`<svg viewBox="0 0 320 150" role="img" aria-label="Brazo de máquina cargado con discos alrededor de un eje"><circle cx="62" cy="103" r="9" class="machine-pivot"/><path d="M62 103 L221 52" class="machine-bar"/><circle cx="226" cy="50" r="18" class="machine-plate"/><circle cx="226" cy="50" r="7" class="machine-pivot"/><line x1="226" y1="71" x2="226" y2="118" class="machine-force"/><path d="M220 112 L226 123 L232 112" class="machine-arrow"/><line x1="62" y1="103" x2="226" y2="103" class="machine-arm"/><text x="81" y="94">distancia perpendicular</text><text x="247" y="112">gravedad</text></svg>`,mechanism:'Los discos ejercen una fuerza gravitatoria sobre el brazo de la máquina. Su torque varía durante el giro porque cambia la distancia perpendicular entre la línea de gravedad y el eje. El punto donde la persona empuja determina, aparte, el torque externo en sus articulaciones.',watch:'La misma cantidad de discos puede sentirse distinta según el radio de montaje, el ángulo y la longitud del brazo. En prensa, remo y press también importan el recorrido guiado y las fuerzas de contacto; no se puede deducir la carga articular desde los discos solamente.',sources:['simplemachines','torque','machinelever']}
];

